```bash
// Step 1: Build the application
// Terminal command: mvn clean package
// Output: target/order-service-1.0.0.jar (example: 35 MB)

// Step 2: Run with default configuration
// Terminal command: java -jar target/order-service-1.0.0.jar

// Step 3: Run with custom port and profile
// Terminal command:
java -jar target/order-service-1.0.0.jar \
  --server.port=9090 \
  --spring.profiles.active=production

// Step 4: Run with JVM arguments for production
// Terminal command:
java -Xmx512m -Xms256m \
  -Dspring.config.location=/etc/myapp/application.properties \
  -jar target/order-service-1.0.0.jar

// Step 5: Run in background (Linux/Mac)
// Terminal command:
nohup java -jar target/order-service-1.0.0.jar \
  > application.log 2>&1 &

// Check the process
// Terminal command: ps aux | grep order-service
