package com.example.demo;

import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/products")
public class ProductController {

    @GetMapping
    public List<String> getProducts() {
        return List.of("Laptop", "Mouse", "Keyboard");
        // Save this file after adding DevTools
        // Watch console: "Restarting due to changes..."
        // Restart completes in ~2 seconds
    }
}

// Workflow:
// 1. Run: mvn spring-boot:run
// 2. Edit ProductController, add "Monitor" to the list
// 3. Save file (IDE auto-compiles)
// 4. DevTools detects change, restarts automatically
// 5. Refresh browser — new product appears
