@SpringBootApplication
public class OrderApplication extends SpringBootServletInitializer {
    @Override
    protected SpringApplicationBuilder configure(SpringApplicationBuilder b) {
        return b.sources(OrderApplication.class);  // lets an external container boot it
    }
    public static void main(String[] args) {
        SpringApplication.run(OrderApplication.class, args);
    }
}
// pom.xml: <packaging>war</packaging>  ->  drop the .war into an external Tomcat
